const body = $input.item.json.body || $input.item.json;
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const db = `${prj}/IMPAR_OS/database/impar.db`;
const { execSync } = require('child_process');
const ts = new Date().toISOString();
const reason = (body.reason||'').substring(0,200);
const caller = (body.caller||'unknown').substring(0,50);
const escalation_steps = body.escalation_steps || [];
if (!reason) return [{ json: { error: 'reason_required', ai_used: false, message: 'Informe o motivo do escalonamento para IA e as etapas determinísticas já tentadas.' } }];
try {
  const safeReason = reason.replace(/'/g,"''");
  const safeCaller = caller.replace(/'/g,"''");
  execSync(`sqlite3 "${db}" "INSERT INTO ai_usage (timestamp,caller,reason,tokens_estimated,avoided,cache_hit) VALUES ('${ts}','${safeCaller}','${safeReason}',0,0,0);"`, {timeout:5000});
} catch(e) {}
return [{ json: { status: 'escalated', ai_used: true, timestamp: ts, reason, caller, escalation_steps, message: 'Escalonamento registrado. Invoke Claude Code manualmente com contexto mínimo.', warning: 'Use IA apenas quando todas as regras determinísticas falharam.' } }];
